The set $R_{\operatorname{ideal}}$ is polyhedral, and $R_{\operatorname{ideal}} = R_{\operatorname{cayley}}$.

The Cayley embedding $R_{\operatorname{cayley}}$ is equal to all $(x,y,z)$ satisfying
\begin{subequations}
\begin{align}
    y \leq \overline{\alpha} \cdot x + \sum_{k=1}^d \left(\max_{x^k \in D_{|k}}\{(w^k - \overline{\alpha}) \cdot x^k\} + b^k\right)z_k&\quad\forall \overline{\alpha} \in \mathbb{R}^\eta\\
    y \geq \underline{\alpha} \cdot x + \sum_{k=1}^d \left(\min_{x^k \in D_{|k}}\{(w^k - \underline{\alpha}) \cdot x^k\} + b^k\right)z_k&\quad\forall \underline{\alpha} \in \mathbb{R}^\eta\\
    (x,y,z) \in D \times \mathbb{R} \times \Delta^d.
\end{align}
\end{subequations}

The system describing $\Set{(x,y,z) \in R_{\operatorname{sharp}} | z \in \{0,1\}^d}$ is a hereditarily sharp MIP formulation of $S_{\operatorname{max}}$.

The set $R_{\operatorname{sharp}}$ is equal to all $(x,y,z)$ such that
\begin{subequations}
\begin{align}
    y \leq \alpha \cdot x + \sum_{k=1}^d \left(\max_{x^k \in D}\{(w^k - \alpha) \cdot x^k\} + b^k\right)z_k&\quad\forall \alpha \in \mathbb{R}^\eta\\
    y \geq w^k \cdot x + b^k&\quad\forall k \in \llbracket d \rrbracket\\
    (x,y,z) \in D \times \mathbb{R} \times \Delta^d. 
\end{align}
\end{subequations}

If $d=2$, then at any values of $(x,z)$ where $\overline{g}(x,z)\ge\underline{g}(x,z)$ (i.e. there exists a $y$ such that $(x,y,z) \in R_{\operatorname{cayley}}$), we have
    \begin{align*}
        \underline{g}(x,z) = \max\{w^1 \cdot x + b^1, w^2 \cdot x + b^2\}.
    \end{align*}

If $d = 2$, then at any values of $(x,z)$ where $\overline{g}(x,z)\ge\underline{g}(x,z)$ (i.e. there exists a $y$ such that $(x,y,z) \in R_{\operatorname{cayley}}$), we have
\begin{align}

\overline{g}(x,z) = \max_{\widetilde{x}^1, \widetilde{x}^2}\Set{w^1 \cdot \widetilde{x}^1 + b^1 z_1 + w^2 \cdot \widetilde{x}^2 + b^2 z_2 | \begin{array}{l} x = \widetilde{x}^1 + \widetilde{x}^2 \\ \widetilde{x}^1 \in z_1 \cdot D \\ \widetilde{x}^2 \in z_2 \cdot D \end{array}}.
\end{align}

When $d=2$, $\Set{(x,y,z) \in R_{\operatorname{sharp}} | z \in \{0,1\}^d}$ is an ideal MIP formulation of $S_{\operatorname{max}}$.

For any fixed $x \in \Delta^{p}$ and $z \in \Delta^d$,
\begin{align} 
    \min_{\alpha} \left( \sum_{j=1}^{p}\alpha_{j}x_{j} + \sum_{k=1}^dz_k\cdot\max_{j=1}^p(w^k_{j} - \alpha_{j}) \right) = \mathsf{Transport}(x,z;w^1,\ldots,w^d).
\end{align}

Therefore, when $D$ is a product of simplices, the constraints (12a) can be replaced in (12) with the single inequality
\begin{align} 

y\le\sum_{i=1}^{\tau}\mathsf{Transport}((x_{i,j})_{j=1}^{p_i},z;(w^1_{i,j})_{j=1}^{p_i},\ldots,(w^d_{i,j})_{j=1}^{p_i})+\sum_{k=1}^db^kz_k.

\end{align}

Given data $w^1, w^2 \in \mathbb{R}^p$, take $\widetilde{w}_j = w^1_j-w^2_j$ for all $j\in\llbracket p\rrbracket$, and suppose the indices have been sorted so that
$\widetilde{w}_1\le\cdots\le\widetilde{w}_p$.
Then
\begin{align} 

\mathsf{Transport}(x,z;w^1,w^2)=\min_{J=1}^{p}\left(\widetilde{w}_Jz_1+\sum_{j=J+1}^{p}(\widetilde{w}_j-\widetilde{w}_J)x_j\right)+\sum_{j=1}^{p}w^2_jx_j.
\end{align}
Moreover, a $J \in \llbracket p \rrbracket$ that attains the minimum in the right-hand side of (18) can be found in $\mathcal{O}(p)$ time.

Suppose that $d=2$ and that $D$ is a product of simplices.  Let $z = z_1 \equiv 1-z_2$.
For each simplex $i \in \llbracket \tau \rrbracket$, take $\widetilde{w}_{i,j} = w^1_{i,j}-w^2_{i,j}$ for all $j=1,\ldots,p_i$ and relabel the indices so that $\widetilde{w}_{i,1}\le\cdots\le\widetilde{w}_{i,p_i}$.
Then, in the context of (12), the upper-bound constraints (12a) are equivalent to
\begin{align}
&y\le\sum_{i=1}^{\tau}\left(\widetilde{w}_{i,J(i)}z+\sum_{j=J(i)+1}^{p_i}(\widetilde{w}_{i,j}-\widetilde{w}_{i,J(i)})x_{i,j}+\sum_{j=1}^{p_i}w^2_{i,j}x_{i,j}\right)+(b^1-b^2)z+b^2  \\
&\hspace{9em}\forall\text{ mappings $J:\llbracket\tau\rrbracket\to\mathbb{Z}$ with $J(i)\in\llbracket p_i\rrbracket\ \forall i\in\llbracket\tau\rrbracket$.} 
\end{align}
Moreover, given any point $(x,y,z)\in D\times\mathbb{R}\times[0,1]$, feasibility can be verified or a most violated constraint can be found in $\mathcal{O}(p_1+\cdots+p_{\tau})$ time.

Given data $w^1, \ldots, w^d \in \mathbb{R}^2$, take $\widetilde{w}^k = w^k_1 - w^k_2$ for all $k\in\llbracket d\rrbracket$, and suppose the indices have been sorted so that
$\widetilde{w}^1\le\cdots\le\widetilde{w}^d$.
Then
\begin{align} 

\mathsf{Transport}(x,z;w^1,\ldots,w^d)=\min_{K=1}^d\left(\widetilde{w}^Kx_1+\sum_{k=1}^{K}w^k_2z_k+\sum_{k=K+1}^{d}(w^k_1-\widetilde{w}^K)z_k\right).
\end{align}
Moreover, a $K \in \llbracket d \rrbracket$ that attains the minimum in the right-hand side of (22) can be found in $\mathcal{O}(d)$ time.

Therefore, suppose that $D$ is a product of $\tau$ simplices of dimensions $p_1=\cdots=p_{\tau}=2$.
For each simplex $i\in\llbracket\tau\rrbracket$, take $\widetilde{w}^k_i=w^k_{i,1}-w^k_{i,2}$ for all $k=1,\ldots,d$ and relabel the indices so that $\widetilde{w}^1_i\le\cdots\le\widetilde{w}^d_i$.
Then, in the context of (12), the upper-bound constraints (12a) are equivalent to
\begin{align}
y &\le\sum_{i=1}^{\tau}\left(\widetilde{w}^{K(i)}_ix_{i,1}+\sum_{k=1}^{K(i)}w^k_{i,2}z_k+\sum_{k=K(i)+1}^{d}(w^k_{i,1}-\widetilde{w}^{K(i)}_i)z_k\right)+\sum_{k=1}^db^kz_k  \\
&\hspace{18em}\forall\text{ mappings $K:\llbracket\tau\rrbracket\to\llbracket d\rrbracket$.} 
\end{align}
Furthermore, none of the constraints in~(23) are redundant.

Presume that the input domain $D = \Delta^{p_1} \times \cdots \times \Delta^{p_\tau}$ is a product of $\tau$ simplices, and that $f(x) = \sum_{i=1}^\tau \sum_{j=1}^{p_i} w_{i,j} x_{i,j} + b$ is an affine function. Presume that, for each $i \in \llbracket \tau \rrbracket$, the weights are sorted such that $w_{i,1} \leq \cdots \leq w_{i,p_i}$. Then an ideal formulation for $\operatorname{gr}(\emph{\texttt{ReLU}{}} \circ f; D)$ is:
    \begin{subequations}
    \begin{gather}
        y \geq w \cdot x + b \\
        \begin{aligned}
        y \leq \sum_{i=1}^\tau \left( w_{i,J(i)} z + \sum_{j=J(i)+1}^{p_i} (w_{i,j} - w_{i,J(i)})x_{i,j} \right) + bz  \\
        \forall\text{ mappings $J:\llbracket\tau\rrbracket\to\mathbb{Z}$ with $J(i)\in\llbracket p_i\rrbracket\ \forall i\in\llbracket\tau\rrbracket$} \end{aligned} \\
        (x,y,z) \in D \times \mathbb{R}_{\geq 0} \times \{0,1\}.
    \end{gather}
    \end{subequations}
    Moreover, a most-violated constraint from the family (29b), if one exists, can be identified in $\mathcal{O}(p_1+\cdots+p_\tau)$ time. Finally, none of the constraints from (29b) are redundant.

For each $k, \ell \in \llbracket d \rrbracket$, take
    \begin{align*}
        N^{\ell,k} &= \sum_{i=1}^\eta \max\{(w^k_i-w^\ell_i)L_i, (w^k_i-w^\ell_i)U_i)\}.
    \end{align*}
    A valid MIP formulation for $\operatorname{gr}(\emph{\texttt{Max}{}} \circ (f^1,\ldots,f^d); [L,U])$ is
    \begin{subequations} 
    \begin{align}
    &y \leq w^\ell \cdot x + \sum_{k=1}^d \left(N^{\ell,k} + b^k\right)z_k \quad \forall \ell \in \llbracket d \rrbracket  \\
   &y \geq w^k \cdot x + b^k \quad\forall k \in \llbracket d \rrbracket  \\
    &(x,y,z) \in [L,U] \times \mathbb{R} \times \Delta^d \\
    &z \in \{0,1\}^d.
    \end{align}
    \end{subequations}
    Moreover, a hereditarily sharp formulation is given by (24), along with the constraints
\begin{align}
&y \leq \sum_{i=1}^{\eta}\left(w^{I(i)}_ix_i+\sum_{k=1}^d\max\{(w^{k}_i-w^{I(i)}_i)L_i,(w^{k}_i-w^{I(i)}_i)U_i\}z_k\right)+\sum_{k=1}^db^kz_k\\ &\hspace{19em}\forall \text{ mappings } I : \llbracket \eta \rrbracket \to \llbracket d \rrbracket 
\end{align}








Furthermore, none of the constraints~(24b) and~(25) are redundant.

Consider the family of inequalities~(25). Take some point $(\hat{x},\hat{y},\hat{z}) \in [L,U] \times \mathbb{R} \times \Delta^d$. If any constraint in the family is violated at the given point, a most-violated constraint can be constructed by selecting $\hat{I} : \llbracket \eta \rrbracket \to \llbracket d \rrbracket$ such that
\begin{equation}
        \hat{I}(i) \in \arg\min_{\ell\in\llbracket d\rrbracket} \left( w^{\ell}_i\hat{x}_i+\sum_{k=1}^d\max\{(w^{k}_i-w^{\ell}_i)L_i,(w^{k}_i-w^{\ell}_i)U_i\}\hat{z}_k \right) 
\end{equation}
for each $i \in \llbracket \eta \rrbracket$. Moreover, if the weights $w_i^k$ are sorted on $k$ for each $i \in \llbracket \eta \rrbracket$, this can be done in $\mathcal{O}(\eta d)$ time.

Take some affine function $f(x) = w \cdot x + b$ over input domain $D = [L,U]$. The following is a valid formulation for $\operatorname{gr}(\emph{\texttt{Leaky}{}} \circ f; [L,U])$:
    \begin{subequations} 
    \begin{align}
        y &\geq f(x)  \\
        y &\geq \alpha f(x)  \\
        y &\leq f(x) - (1-\alpha) \cdot M^-(f; [L,U]) \cdot (1-z)  \\
        y &\leq \alpha f(x) - (\alpha-1) \cdot M^+(f; [L,U]) \cdot z  \\
        (x,y,z) &\in [L,U] \times \mathbb{R} \times [0,1] \\
        z &\in \{0,1\}.
    \end{align}
    \end{subequations}
    Moreover, an ideal formulation is given by (30), along with the constraints
    \begin{align} 
        y \leq& \left(\sum_{i \in I} w_i(x_i - \breve{L}_i(1-z)) + \left(b + \sum_{i \not\in I} w_i\breve{U}_i\right)z\right)  \\
        & + \alpha\left(\sum_{i \not\in I} w_i(x_i - \breve{U}_iz) + \left(b + \sum_{i \in I} w_i\breve{L}_i\right)(1-z)\right) \quad \forall I \subseteq \llbracket \eta \rrbracket.
    \end{align}
    Additionally, the most violated inequality from the family (31) can be separated in $\mathcal{O}(\eta)$ time. Finally, each inequality in \emph{(30a--30d)} and (31) is facet-defining.
